": \"./lib/components/background/package.json\",\n    \"./background/locale/*.json\": \"./lib/components/background/locale/*.json\",\n    \"./background/icon\": \"./lib/components/background/icon.png\",\n    \"./ptc\": {\n      \"default\": \"./lib/components/ptc/index.js\"\n    },\n    \"./ptc-sdk\": {\n      \"types\": \"./lib/ptc/sdk.d.ts\"\n    },\n    \"./ptc/package.json\": \"./lib/components/ptc/package.json\",\n    \"./ptc/locale/*.json\": \"./lib/components/ptc/locale/*.json\",\n    \"./ptc/icon\": \"./lib/components/ptc/icon.png\",\n    \"./panel\": {\n      \"default\": \"./lib/components/panel/index.js\"\n    },\n    \"./panel/package.json\": \"./lib/components/panel/package.json\",\n    \"./panel/locale/*.json\": \"./lib/components/panel/locale/*.json\",\n    \"./panel/icon\": \"./lib/components/panel/icon.png\",\n    \"./tui\": {\n      \"default\": \"./lib/components/tui/index.js\"\n    },\n    \"./tui/package.json\": \"./lib/components/tui/package.json\",\n    \"./tui/locale/*.json\": \"./lib/components/tui/locale/*.json\",\n    \"./tui/icon\": \"./lib/components/tui/icon.png\",\n    \"./discovery\": {\n      \"default\": \"./lib/components/discovery/index.js\"\n    },\n    \"./discovery/package.json\": \"./lib/components/discovery/package.json\",\n    \"./discovery/locale/*.json\": \"./lib/components/discovery/locale/*.json\",\n    \"./discovery/icon\": \"./lib/components/discovery/icon.png\",\n    \"./download-guard\": {\n      \"default\": \"./lib/components/download-guard/index.js\"\n    },\n    \"./download-guard/package.json\": \"./lib/components/download-guard/package.json\",\n    \"./download-guard/locale/*.json\": \"./lib/components/download-guard/locale/*.json\",\n    \"./download-guard/icon\": \"./lib/components/download-guard/icon.png\",\n    \"./hide-official\": {\n      \"default\": \"./lib/components/hide-official/index.js\"\n    },\n    \"./hide-official/package.json\": \"./lib/components/hide-official/package.json\",\n    \"./hide-of