hipped in the npm package (bench 只存在于仓库,不随包发布); run npm run bench:* from a dsh-ops checkout');process.exit(2)};process.exit(require('node:child_process').spawnSync(process.execPath,['bench/cli.mjs','tools',...process.argv.slice(1)],{stdio:'inherit'}).status??1)\\\" --\",\n    \"stage:niubash\": \"node scripts/lib/build/niubash.mjs\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.1.0\",\n    \"@deepseek-ai/dsh\": \">=0.2.2-rc.1 <0.2.3-0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.1.0\",\n    \"@deepseek-ai/cordis-plugin-group\": \"1.1.0\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.1.0\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.1.0\",\n    \"@deepseek-ai/cosmokit\": \"1.9.0\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-api-remotes\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-app-boot\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-modules\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-plugin-manager\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-config-editor\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-fs-local\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-fs-observation-policy\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-jobs-local\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-ptc-runtime-node\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-sandbox-local\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-scope\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-settings\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-subprocess-local\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tool-call-timeout-policy\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tool-executor-native\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tool-executor-ptc\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tool-fs\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tool-fs-search\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/dsh-working-directory\": \"0.2.2-rc.1\",\n    \"@deepseek-ai/schemastery\": \"3.19.0\",\n    \"@dsh-std/manifest\": \"0.1.1-rc.3\",\n    \"@types/node\": \"22.20.5\",\n    \"@types/react\": \"18.3.1\",\n    \"@types/react-dom\": \"18.3.0\",\n    \"js-tiktoken\": \"1.0.21\",\n    \"jsdom\": \"26.1.0\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"typescript\": \"6.0.3\",\n    \"yaml\": \"^2.9.1\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19 || >=24\",\n    \"dsh\": \">=0.2.2-rc.1 <0.2.3-0\"\n  }\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# One row, named exactly like the package: dsh-client-modules mounts a package's\n# browser half on the row whose specifier is the package name, so this row also\n# carries the Plugins-page configuration for every feature.\n#\n# Each section owns its enable switch and only the keys that feature reads. The\n# data capture and the TUI integration stay off by default. Legacy component modules (mode-*, discovery, panel, tui, shell,\n# file, ptc, hide-official, background) remain exported: a saved override for one\n# of those specifiers still loads its legacy module, it just cannot match this row.\n- insert:\n    - id: dsh-ops\n      name: dsh-ops\n      config:\n        # Four bundle switches (one per preset switch), then each preset; all default on.\n        global:\n          bash: true\n          hidePwsh: true\n          hideOfficialTools: true\n          dynamicTools: true\n        minimal:\n          enabled: true\n          spillRetentionDays: 30\n          spillTotalBudgetMiB: 256\n          spillSweepEnabled: true\n        standard:\n          enabled: true\n          residentTools: true\n          spillRetentionDays: 30\n          spillTotalBudgetMiB: 256\n          spillSweepEnabled: true\n        ptc:\n          enabled: true\n          residentTools: true\n          spillRetentionDays: 30\n          spillTotalBudgetMiB: 256\n          spillSweepEnabled: true\n        cordis:\n          enabled: true\n          residentTools: true\n          spillRetentionDays: 30\n          spillTotalBudgetMiB: 256\n          spillSweepEnabled: true\n        discovery:\n          enabled: true\n        # Inert until template is set; off by default so an install that never\n        # opted in gets no listener at all.\n        download-guard:\n          enabled: false\n          downloadGuard:\n            template: \"\"\n        # Result-cache retention. The aggregate budgets stay 0 (report only): the default sweep\n        # only reclaims roots whose cache data is already gone. maxAgeMs is the idle grace that\n        # protects another live host sharing the temp directory.\n        resultCache:\n          enabled: true\n          maxRoots: 0\n          maxTotalBytes: 0\n          maxAgeMs: 3600000\n          sweepEnabled: true\n        panel:\n          enabled: false\n        tui:\n          enabled: false\n        # Read-only disk ownership reporting. The retention block is a validated\n        # contract only: this release evicts nothing.\n        disk:\n          status:\n            includeRepository: false\n            maxEntries: 5000\n          retention:\n            enabled: false\n            maxAgeDays: 0\n            maxBytes: 0\n"
    },
    {
      "path": "src/presets/defaults.ts",
      "content": "/**\n * What each mode contributes to a session of its preset.\n *\n * This table is the product contract between the four mode rows and the shared\n * publication controllers: resident OPS tools, official tools replaced once\n * their OPS counterpart is visible, and whether the mode consumes the advanced\n * file tools through the discovery entry.\n */\nimport type { OfficialReplacement } from '../capabilities/replacements.js'\nimport { publicToolName } from '../policy.js'\nimport type { ModeId } from './types.js'\n\nimport { NATIVE_RESIDENT_RAW, SHELL_OFFICIAL_NAMES } from '../capabilities/profiles.js'\nexport { NATIVE_RESIDENT_RAW, SHELL_OFFICIAL_NAMES } from '../capabilities/profiles.js'\n\n/** One mode's publication and replacement policy. */\nexport interface ModePlan {\n  /** Publish the resident native file tools for matching Agents. */\n  nativeFiles: boolean\n  /** Official file tools replaced once their OPS counterpart is visible in the same scope. */\n  replacements: readonly OfficialReplacement[]\n  /** Publish the independent OPS Bash tool when the row is on. */\n  shell: boolean\n  /** Publish the PTC SDK APIs for matching Agents. */\n  ptc: boolean\n  /** Progressive discovery population for matching Agents. */\n  discovery: 'none' | 'advanced' | 'all'\n  /** The mode's routing section suffix; null publishes no routing text. */\n  section: string | null\n}\n\nconst NATIVE_REPLACEMENTS: readonly OfficialReplacement[] = Object.freeze(['read', 'glob', 'grep'])\n\n/** Everything one mode publishes; consumers read this instead of branching on ids. */\nexport const MODE_PLANS: Readonly<Record<ModeId, ModePlan>> = Object.freeze({\n  // Minimal keeps its terse prompts: OPS Bash is published independently, and\n  // advanced tools arrive through the discovery entry when that row is on.\n  minimal: Object.freeze({ nativeFiles: false, replacements: [], shell: true, ptc: false, discovery: 'all', section: null }),\n  standard: Object.freeze({ nativeFiles: true, replacements: NATIVE_REPLACEMENTS, shell: true, ptc: false, discovery: 'advanced', section: 'standard' }),\n  ptc: Object.freeze({ nativeFiles: false, replacements: [], shell: true, ptc: true, discovery: 'none', section: 'ptc' }),\n  cordis: Object.freeze({ nativeFiles: true, replacements: NATIVE_REPLACEMENTS, shell: true, ptc: false, discovery: 'advanced', section: 'cordis' }),\n})\n\n/**\n * The resident native capability names of one mode.\n * @param mode - the mode to read.\n * @returns public OPS names, or an empty list when the mode publishes no native file tools.\n */\nexport function residentTools(mode: ModeId): readonly string[] {\n  return MODE_PLANS[mode].nativeFiles ? NATIVE_RESIDENT_RAW.map(raw => publicToolName(raw)) : []\n}\n"
    },
    {
      "path": "src/index.ts",
      "content": "/** Single-row composition root. All presets consume the same assembly pipeline. */\nimport type { Context } from './adapter/dsh/types.js'\nimport { applyResolvedMode } from './presets/builtin.js'\nimport { resolveModeConfig } from './presets/config.js'\nimport { resolveMergedConfig, effectiveMode, dynamicForMode } from './settings/merged.js'\nimport { beginMergedRow, endMergedRow } from './settings/legacy.js'\nimport { mountIntegration } from './integration/index.js'\nimport { gateConsumer } from './consumer/gates.js'\nimport { resolveIntegrationConfig } from './consumer/options.js'\nimport { mountRuntimeSettings } from './settings/runtime-host.js'\nimport { companionVersion } from './settings/companion.js'\nimport * as panelModule from './components/panel/index.js'\nimport * as tuiModule from './components/tui/index.js'\nimport * as downloadGuardModule from './components/download-guard/index.js'\nimport { configureResultCacheGc } from './kernel/result-cache-gc.js'\nexport { Config } from './settings/merged.js'\nexport { applyComponent } from './legacy/host.js'\nexport const name = 'dsh-ops'\n\n/**\n * Package-root entry: the single row the bundle inserts.\n *\n * Every feature the row enables is mounted from this one fiber with its own\n * validated slice. Disabling a feature and saving the row remounts the fiber, so\n * its effects are torn down exactly like the old per-row switches did. The TUI\n * link keeps its optional host service: an absent `tuiPanels` leaves that\n * desktop feature pending instead of blocking the tools.\n */\n\nexport async function apply(root: Context, rawConfig: unknown): Promise<void> {\n  const config = resolveMergedConfig(rawConfig)\n  const host = root\n  const mount = async (module: { apply(...args: unknown[]): unknown }, state: { enabled: boolean; raw?: Record<string, unknown>; config: unknown }, slice?: Record<string, unknown>): Promise<void> => {\n    if (!state.enabled) return\n    const payload = slice ?? state.raw ?? state.config\n    if (state.raw === undefined && slice === undefined) {\n      await host.plugin({ name: `dsh-ops/${moduleName(module)}`, apply: (ctx: Context) => { (module.apply as (ctx: Context, config: unknown) => void)(ctx, state.config) } })\n      return\n    }\n    await host.plugin(module, payload)\n  }\n  // The retention sweep is process-wide (it scans the temp directory once per start-up and once\n  // per shutdown), so its validated budget is installed here instead of inside each consumer.\n  const retention = config.resultCache\n  configureResultCacheGc(retention.enabled ? retention.config : undefined)\n  root.effect(() => () => configureResultCacheGc(undefined), 'dsh-ops: result cache retention')\n  beginMergedRow()\n  try {\n    // The browser half mounts its `opsSettings` remote; the legacy shell row used\n    // to provide that seam, so the merged row owns it now.\n    await host.plugin({ name: 'dsh-ops/runtime-settings', apply: (ctx: Context) => mountRuntimeSettings(ctx, { config: () => rawConfig }) })\n    for (const mode of ['minimal', 'standard', 'ptc', 'cordis'] as const) {\n      const state = config[mode]\n      const effective = resolveModeConfig(effectiveMode(state, config.global, typeof config.other.raw?.pwsh7Link === 'boolean' ? config.other.raw.pwsh7Link : companionVersion({ sweep: false }) !== undefined), mode)\n      await host.plugin({ name: `dsh-ops/consumer-${mode}`, apply(ctx: Context) {\n        applyResolvedMode(ctx, effective, mode, { enabled: state.enabled,\n          discovery: { ...config.discovery.config, enabled: config.discovery.enabled },\n          dynamic: dynamicForMode(state, config.global) })\n      } })\n    }\n    for (const row of Object.values(config.presets)) {\n      const options = row.options\n      const resolved = resolveIntegrationConfig(options)\n      const linked = typeof config.other.raw?.pwsh7Link === 'boolean' ? config.other.raw.pwsh7Link : companionVersion({ sweep: false }) !== undefined\n      const effective = gateConsumer(resolved, config.global, linked)\n      await host.plugin({ name: `dsh-ops/custom-${resolved.preset}`, apply(ctx: Context) { return mountIntegration(ctx, effective) } })\n    }\n    await mount(downloadGuardModule, config['download-guard'], { downloadGuard: config['download-guard'].config })\n    await mount(panelModule, config.panel)\n    await mount(tuiModule, config.tui)\n  } finally { endMergedRow() }\n}\n\n/** The module's declared name, for the child plugin label. */\nfunction moduleName(module: unknown): string {\n  const value = (module as { name?: unknown }).name\n  return typeof value === 'string' ? value : 'feature'\n}\n"
    },
    {
      "path": "src/consumer/mount.ts",
      "content": "/** One assembly path: consumers supply policy, publishers own registration and execution. */\nimport type { Agent, Context } from '../adapter/dsh/types.js'\nimport { resolveShells } from '../shells.js'\nimport { mountSessionBash } from '../session-shells.js'\nimport { mountWorkspacePreparation } from '../workspace-preparation.js'\nimport { mountNative } from '../publication/native.js'\nimport { mountReplacements } from '../publication/replacements.js'\nimport { mountDiscovery } from '../discovery/controller.js'\nimport { mountPtc } from '../publication/ptc.js'\nimport { NATIVE_RESIDENT_RAW } from '../capabilities/profiles.js'\nimport { BASH_TOOL, publicToolName } from '../policy.js'\nimport { BASH_PROMPT_SECTION, renderBashGuidance } from '../shells/prompt.js'\nimport { mountJobWaitGuidance } from '../shells/job-wait-guidance.js'\nimport { mountSpillRetention } from '../shells/spill-retention-runtime.js'\nimport { spillRetentionConfig } from '../shells/spill-retention.js'\nimport type { ConsumerPlan } from './types.js'\n\nexport function mountConsumer(ctx: Context, plan: ConsumerPlan): void {\n  const { gate, core } = plan\n  let renderShellGuidance: (agent: Agent) => string = () => ''\n  const shellOwnsGuidance = (agent: Agent): boolean => Boolean(renderShellGuidance(agent))\n  if (plan.shell) {\n    // Host subprocess spills outlive the call that produced them upstream, so the\n    // row that publishes the shell also owns one bounded retention runtime.\n    const releaseSpillRetention = mountSpillRetention(spillRetentionConfig(core), {\n      report: message => ctx.logger?.warn?.(message),\n    })\n    ctx.effect(() => () => releaseSpillRetention(), 'dsh-ops: spill retention')\n    if (process.platform === 'win32') mountWorkspacePreparation(ctx)\n    const shells = resolveShells(core)\n    ctx.inject(['tools'], inner => mountSessionBash(inner, core, shells, gate))\n    if (core.promptPolicy) ctx.inject(['tools', 'systemPrompt'], inner => {\n      mountJobWaitGuidance(inner, plan.id, gate)\n      let active = true\n      inner.effect(() => () => { active = false }, 'dsh-ops: Bash guidance lifetime')\n      renderShellGuidance = agent => {\n        if (!active || !agent || !gate.allows(agent)) return ''\n        const definition = inner.get('tools')?.get(BASH_TOOL, agent)\n        if (!definition) return ''\n        const background = Object.hasOwn(definition.parameters.properties ?? {}, 'run_in_background')\n        return [renderBashGuidance(background), core.extraGuidance.trim()].filter(Boolean).join('\\n\\n')\n      }\n      inner.effect(() => inner.systemPrompt.section({ name: `${BASH_PROMPT_SECTION}:${plan.id}`, order: inner.systemPrompt.getSectionOrder('TOOL_BASH'), interpolate: false,\n        text: context => renderShellGuidance(context.agent ?? context.scope as Agent),\n      }), 'dsh-ops: consumer Bash guidance')\n    })\n  }\n  if (plan.presentation === 'native') {\n    const residents = plan.files && plan.residentTools ? (plan.residentNames ?? NATIVE_RESIDENT_RAW) : []\n    const nativeOwnsGuidance = residents.length\n      ? mountNative(ctx, core, { id: plan.id, tools: residents, section: plan.section, gate, extraGuidanceOwner: shellOwnsGuidance })\n      : () => false\n    if (plan.discovery || plan.native.alwaysLoaded.length || plan.external.allowed.length) mountDiscovery(ctx,\n      { ...plan.native, enabled: plan.discovery }, { ...gate, guidance: core.promptPolicy, extraGuidance: core.extraGuidance,\n        extraGuidanceOwner: agent => shellOwnsGuidance(agent) || nativeOwnsGuidance(agent),\n        residentTools: () => residents.map(publicToolName), external: plan.external })\n  } else if (plan.files) mountPtc(ctx, plan.ptc, { ...gate, guidance: core.promptPolicy, resident: plan.residentTools, dynamic: plan.discovery })\n  if (plan.replaceOfficial) mountReplacements(ctx, { id: plan.id, targets: plan.replacementTargets, gate, keepOfficial: () => false })\n}\n"
    },
    {
      "path": "src/publication/native.ts",
      "content": "/** Scoped Native file publication. Callers supply policy; this controller owns lifecycle. */\nimport type { Context, Fiber } from '../adapter/dsh/types.js'\nimport type { Agent } from '../adapter/dsh/types.js'\nimport type {} from '../adapter/dsh/types.js'\nimport { NativeFileTools } from '../projections/native/runtime.js'\nimport { registerNativeProviderAtScope, nativeProviderReady } from './providers.js'\nimport { resolveWorker } from '../execution/files.js'\nimport { mountResultLifecycle } from '../kernel/result-lifecycle.js'\nimport { publicToolName, modeSectionName, MODE_SECTION_ORDERS, renderToolingPolicy } from '../policy.js'\nimport { visibleNames } from './surface.js'\nimport { activationIsPtc, isNativePresentation, isPresentationProbe } from './presentation.js'\nimport type { ResolvedConfig } from '../config.js'\nimport { ownScopes } from './ownership.js'\nimport { failure } from '../execution/files.js'\nimport { acquireSharedFile, isSharedFileApi } from './scope-owner.js'\nimport type { PublicationGate } from './types.js'\nimport { publicationError, publicationReady, publicationRegistration } from './reentry.js'\nimport type { PublicationLease } from './registrar.js'\n\ntype ResidentName = Parameters<NativeFileTools['definition']>[0]\n\ninterface Entry {\n  agent: Agent\n  ctx?: Context\n  fiber?: Fiber\n  runtime: NativeFileTools\n  owned: Set<string>\n  disposers: (() => void)[]\n  ready: Promise<void>\n}\n\n/** The names, guidance and eligibility supplied by one composition. */\nexport interface NativePublication {\n  id: string\n  tools: readonly ResidentName[]\n  section: string | null\n  gate: PublicationGate\n  extraGuidanceOwner?(agent: Agent): boolean\n}\n\nexport function mountNative(root: Context, config: ResolvedConfig, publication: NativePublication): (agent: Agent) => boolean {\n  const { id: mode, tools: names, section, gate } = publication\n  let ownsGuidance: (agent: Agent) => boolean = () => false\n  let worker: string\n  try { worker = resolveWorker({ binaryPath: config.binaryPath }) } catch (error) {\n    if (config.required) throw error\n    root.logger.warn(`dsh-ops: ${mode} mode cannot resolve its native worker; native file tools stay unpublished. ${String((error as Error)?.message ?? error)}`)\n    return () => false\n  }\n  root.inject(['tools', 'systemPrompt', 'sandboxPolicy', 'subprocess'], async ctx => {\n    const tools = ctx.get('tools')\n    const prompt = ctx.get('systemPrompt')\n    if (!tools || !prompt) return\n    mountResultLifecycle(ctx)\n    const entries = new Map<Agent, Entry>()\n    let stopped = false, mutating = false\n    const ownership = await ownScopes(ctx, 'native-files', () => reconcile(), gate.allows)\n    const clear = (entry: Entry): void => {\n      entry.owned.clear()\n      for (const dispose of entry.disposers.splice(0)) {\n        try { dispose() } catch (error) { ctx.logger.warn(`dsh-ops: ${mode} native publication cleanup failed: ${String(error)}`) }\n      }\n      entry.runtime.cancel('Mode row ownership changed')\n      void entry.runtime.stop().catch(error => ctx.logger.warn(`dsh-ops: ${mode} native runtime stop failed: ${String(error)}`))\n    }\n    const publish = async (agent: Agent, entry: Entry): Promise<void> => {\n      if (!entry.ctx) return\n      const scope = agent\n      const leases: PublicationLease[] = [], registrations: (() => void)[] = []\n      for (const api of names.filter(isSharedFileApi)) {\n        const lease = await acquireSharedFile(agent, api, { workerPath: worker, required: true, denyCredentialReads: config.denyCredentialReads })\n        if (stopped || entries.get(agent) !== entry || !cover(agent)) { lease.dispose(); return }\n        entry.disposers.push(() => lease.dispose())\n        lease.grant({ consumer: entry, agent, token: {}, entitled: true,\n          dispatch: async () => undefined,\n          present: async activation => activation.agent === agent && cover(agent) && !await activationIsPtc(prompt, activation) })\n        leases.push(lease)\n        entry.owned.add(publicToolName(api))\n      }\n      const definitions = names.filter(name => !isSharedFileApi(name)).map(name => {\n        const definition = entry.runtime.definition(name)\n        return { ...definition, execute: async (args: unknown, exec: Parameters<typeof definition.execute>[1]) => {\n          if (stopped || entries.get(agent) !== entry || !cover(agent) || exec.agent !== agent\n            || !await isNativePresentation(prompt, agent, exec.signal).catch(() => false) || stopped || !cover(agent)\n            || tools.executable(definition.name, agent, exec.toolSet) !== registration(definition.name)) {\n            return failure('POLICY_DENIED', 'Native capability belongs to a different or inactive scope.')\n          }\n          return definition.execute(args, exec)\n        } }\n      })\n      const registration = (name: string) => definitions.find(definition => definition.name === name)\n      if (definitions.length) {\n        const dispose = registerNativeProviderAtScope(entry.ctx, scope, definitions, tool => {\n          const remove = publicationRegistration(entry.ctx!, () => entry.ctx!.tools.register(tool, { when: async activation => activation.agent === agent && cover(agent)\n            && !await activationIsPtc(prompt, activation) }))\n          registrations.push(remove)\n          return remove\n        }, { inheritable: false, priority: 10 })\n        entry.disposers.push(dispose)\n      }\n      for (const definition of definitions) entry.owned.add(definition.name)\n      await Promise.all([...leases.map(lease => lease.ready()), ...registrations.map(publicationReady), ...entry.disposers.map(nativeProviderReady)])\n    }\n    const cover = (agent: Agent): boolean => gate.allows(agent) && ownership.owns(agent)\n    const attach = (agent: Agent): void => {\n      if (stopped || entries.has(agent) || !agent?.ctx) return\n      const entry: Entry = { agent, runtime: new NativeFileTools({ ctx, config: { workerPath: worker, required: config.required, denyCredentialReads: config.denyCredentialReads } }),\n        owned: new Set(), disposers: [], ready: Promise.resolve() }\n      entries.set(agent, entry)\n      entry.ready = Promise.resolve().then(async () => {\n        if (stopped || entries.get(agent) !== entry || !cover(agent)) return\n        entry.fiber = agent.ctx!.plugin({ inject: ['tools'], apply(scoped) { entry.ctx = scoped } })\n        await entry.fiber\n        if (stopped || entries.get(agent) !== entry || !entry.ctx) return\n        await entry.runtime.start([])\n        if (stopped || entries.get(agent) !== entry || !cover(agent)) return\n        await publish(agent, entry)\n      }).catch(async error => {\n        try {\n          if (entries.get(agent) === entry) { detach(agent); await entry.fiber?.dispose() }\n        } catch { ctx.logger.warn(`dsh-ops: ${mode} native attachment cleanup failed`) }\n        ctx.logger.warn(`dsh-ops: ${mode} mode publication failed: ${publicationError(error)}`)\n        throw error\n      })\n      void entry.ready.catch(() => {})\n    }\n    const detach = (agent: Agent): void => {\n      const entry = entries.get(agent)\n      if (!entry) return\n      entries.delete(agent)\n      clear(entry)\n      void Promise.resolve().then(() => entry.fiber?.dispose()).catch(error => {\n        ctx.logger.warn(`dsh-ops: ${mode} native scope disposal failed: ${String(error)}`)\n      })\n    }\n    const reconcile = (): void => {\n      if (stopped || mutating) return\n      mutating = true\n      try {\n        for (const [agent, entry] of entries) if (!cover(agent)) detach(agent)\n        for (const agent of ctx.get('agents')?.list?.() ?? []) if (cover(agent)) attach(agent)\n      } finally { mutating = false }\n    }\n    ctx.on('system-prompt/assemble', async (_assembly, context, next) => {\n      const result = await next()\n      if (!isPresentationProbe(context) && result.sections.some(section => section.name === 'tools:ptc-only' && Boolean(section.text.trim()))) {\n        entries.get(context.scope as Agent)?.runtime.cancel('Native presentation withdrawn')\n      }\n      return result\n    })\n    ctx.on('agent/created', async ({ agent }) => {\n      if (cover(agent)) { attach(agent); await entries.get(agent)?.ready }\n    })\n    ctx.on('agent/disposed', ({ agent }) => detach(agent))\n    ctx.on('session/event', (_session, event) => {\n      // A blank session may select another preset before its first turn; the mode\n      // that no longer matches must withdraw its surface.\n      if ((event as { type: string }).type === 'agent-preset/selected') reconcile()\n    })\n    if (gate.watch) ctx.effect(() => gate.watch!(reconcile), `dsh-ops: ${mode} publication observer`)\n    for (const agent of ctx.get('agents')?.list?.() ?? []) if (cover(agent)) attach(agent)\n    const renderGuidance = (agent: Agent, toolSet?: import('../adapter/dsh/types.js').ResolvedToolSet): string => {\n      if (!agent || stopped || section === null || !config.promptPolicy || !cover(agent)) return ''\n      const entry = entries.get(agent)\n      if (!entry || entry.owned.size === 0) return ''\n      const visible = new Set(visibleNames(tools, agent, toolSet))\n      const published = [...entry.owned].filter(name => visible.has(name))\n      // The same consumer's live Bash section owns deployment guidance first.\n      return renderToolingPolicy({ published, shellComponent: false,\n        extraGuidance: publication.extraGuidanceOwner?.(agent) ? '' : config.extraGuidance })\n    }\n    ownsGuidance = agent => !publication.extraGuidanceOwner?.(agent) && Boolean(renderGuidance(agent))\n    if (section !== null) {\n      const suffix = section\n      ctx.effect(() => prompt.section({\n        name: modeSectionName(suffix), order: MODE_SECTION_ORDERS[suffix] ?? 3250, interpolate: false,\n        text: context => renderGuidance(context.agent ?? context.scope as Agent, context.toolSet),\n      }), `dsh-ops: ${mode} tooling guidance`)\n    }\n    ctx.effect(() => () => {\n      stopped = true\n      for (const agent of [...entries.keys()]) detach(agent)\n      ownership.dispose()\n    }, `dsh-ops: ${mode} native lifecycle`)\n    await Promise.all([...entries.values()].map(entry => entry.ready))\n    ownership.refresh()\n  })\n  return agent => ownsGuidance(agent)\n}\n"
    },
    {
      "path": "src/publication/scope-owner.ts",
      "content": "/** The agent's scoped context outlives all publication consumer leases. */\nimport type { Agent, ToolDefinition } from '../adapter/dsh/types.js'\nimport type { FileToolName } from '../capabilities/registry.js'\nimport { definition } from '../projections/ptc/contract.js'\nimport { publicToolName } from '../policy.js'\nimport { acquire } from './registrar.js'\nimport { loadScopes } from '../adapter/dsh/host.js'\n\n// PTC metadata is cached from the static API contract, not runtime closures.\n// Legacy acquisition is retained for isolated contract tests; production uses the shared source.\nconst contracts = new Map<FileToolName, Omit<ToolDefinition, 'name' | 'execute'>>()\nexport function acquirePtcFile(agent: Agent, api: FileToolName) {\n  if (!agent.ctx) throw new Error('Publication requires an agent scope')\n  let canonical = contracts.get(api)\n  if (!canonical) {\n    const { name: _name, execute: _execute, ...metadata } = definition(api, async () => undefined)\n    canonical = metadata\n    contracts.set(api, canonical)\n  }\n  return acquire(agent.ctx, agent, publicToolName(api), canonical)\n}\n\n/** File parameters and execution/files.invoke are identical for Native and PTC.\n * monitoredInvoke routes FILE_TOOLS before jobs. One runtime preserves authoritative\n * cwd, credentials, CAS, permissions, timeouts and result-session lifecycle. Result\n * uses the shared jobs bridge with its explicit PTC put admission fence.\n */\nimport { NativeFileTools } from '../projections/native/runtime.js'\nimport type { NativeRuntimeConfig } from '../projections/native/runtime.js'\nimport type { PublicationLease } from './registrar.js'\nimport { WORKER_TIMEOUT_MS } from '../execution/protocol.js'\nexport const SHARED_FILE_APIS = ['inspect_local_file', 'replace', 'write_file', 'edit_file', 'copy', 'move', 'remove', 'stat', 'grep', 'glob', 'read_files', 'diff', 'read_table', 'read_docx', 'read_pdf', 'result'] as const\nexport function isSharedFileApi(api: string): api is typeof SHARED_FILE_APIS[number] {\n  return (SHARED_FILE_APIS as readonly string[]).includes(api)\n}\ntype SharedApi = typeof SHARED_FILE_APIS[number]\ntype Canonical = Omit<ToolDefinition, 'name' | 'execute'>\ninterface Source {\n  runtime: NativeFileTools\n  ready: Promise<unknown>\n  refs: number\n  closed: boolean\n  identity: string\n  definitions: Map<SharedApi, { canonical: Canonical; dispatch: ToolDefinition['execute'] }>\n}\nconst runtimes = new WeakMap<Agent, Source>()\nexport async function acquireSharedFile(agent: Agent, api: SharedApi, config: NativeRuntimeConfig): Promise<PublicationLease> {\n  if (!agent.ctx) throw new Error('Shared file source requires an agent scope')\n  const { scopeChainOf } = await loadScopes()\n  agent.ctx.fiber.assertActive()\n  const owner = scopeChainOf(agent).find(scope => runtimes.has(scope as Agent)) as Agent | undefined\n  const runtimeOwner = owner ?? agent\n  // Startup policy is not execution identity once a worker has been selected.\n  const normalized = { workerPath: config.workerPath, required: config.required ?? true,\n    denyCredentialReads: config.denyCredentialReads ?? true,\n    toolCallTimeoutMs: config.toolCallTimeoutMs ?? WORKER_TIMEOUT_MS }\n  const { required: _required, ...executionConfig } = normalized\n  const identity = JSON.stringify(executionConfig)\n  let source = runtimes.get(runtimeOwner)\n  if (source && source.identity !== identity) throw new Error('Conflicting shared file runtime configuration')\n  const stop = (owned: Source): void => {\n    if (owned.closed) return\n    owned.closed = true\n    if (runtimes.get(runtimeOwner) === owned) runtimes.delete(runtimeOwner)\n    owned.runtime.cancel('Shared file source disposed')\n    // dispose() is synchronous; explicitly handle asynchronous teardown rejection.\n    void owned.runtime.stop().catch(error => agent.ctx!.logger.warn(`dsh-ops: shared file stop failed: ${String(error)}`))\n  }\n  if (!source) {\n    const runtime = new NativeFileTools({ ctx: agent.ctx, config: normalized })\n    source = { runtime, refs: 0, closed: false, identity, definitions: new Map(), ready: runtime.start([]) }\n    runtimes.set(agent, source)\n    const created = source\n    agent.ctx.effect(() => () => stop(created))\n  }\n  const owned = source\n  ++owned.refs\n  const release = () => { if (--owned.refs === 0) stop(owned) }\n  let lease: PublicationLease\n  let shared: { canonical: Canonical; dispatch: ToolDefinition['execute'] }\n  try {\n    await owned.ready\n    if (owned.closed) throw new Error('Shared file source is disposed')\n    let cached = owned.definitions.get(api)\n    if (!cached) {\n      // runtime.definition retains Native render, metadata and dedup hooks and wraps raw call once.\n      const { name: _name, execute, ...canonical } = owned.runtime.definition(api)\n      cached = { canonical, dispatch: execute }\n      owned.definitions.set(api, cached)\n    }\n    shared = cached\n    lease = await acquire(agent.ctx, agent, publicToolName(api), shared.canonical)\n  } catch (error) { release(); throw error }\n  let disposed = false\n  return {\n    grant: grant => lease.grant({ ...grant, dispatch: shared.dispatch }),\n    ready: () => lease.ready(),\n    dispose() {\n      if (disposed) return\n      disposed = true\n      try { lease.dispose() } finally { release() }\n    },\n  }\n}\n"
    },
    {
      "path": "src/publication/registrar.ts",
      "content": "/** Source-layer publication only; no provider or projection policy lives here. */\nimport type { Agent, Context, ToolDefinition, ToolRunContext, ToolActivationContext } from '../adapter/dsh/types.js'\nimport type { Outcome } from '../kernel/outcome.js'\nimport { loadScopes } from '../adapter/dsh/host.js'\nimport { publicationReady, publicationRegistration } from './reentry.js'\n\nexport interface PublicationGrant {\n  readonly consumer: object\n  readonly agent: Agent\n  readonly token: object\n  /** Captured at grant creation; changing entitlement/token requires revoke + grant. */\n  readonly entitled: boolean\n  dispatch(args: unknown, exec: ToolRunContext): Promise<unknown>\n  /** Presentation may only narrow this captured grant; it never chooses dispatch. */\n  present?(activation: ToolActivationContext): boolean | Promise<boolean>\n  cancel?(): void\n}\nexport interface PublicationLease {\n  grant(grant: PublicationGrant): () => void\n  ready(): Promise<void>\n  dispose(): void\n}\nconst denied = (): Outcome<never> => ({ status: 'rejected', error: { code: 'PUBLICATION_DENIED',\n  effectState: 'none', retry: 'never', message: 'Publication authorization is unavailable.' } })\nconst cancelled = (started: boolean): Outcome<never> => ({ status: started ? 'unknown' : 'rejected', error: {\n  code: started ? 'RESULT_UNKNOWN' : 'ABORTED', effectState: started ? 'unknown' : 'none', retry: 'never',\n  message: started ? 'Invocation cancelled after dispatch; background work may continue.' : 'Invocation cancelled before dispatch.',\n  nextAction: started ? 'Inspect effects before taking further action; do not automatically replay.' : 'Do not retry this cancelled invocation.',\n} })\ntype Canonical = Omit<ToolDefinition, 'name' | 'execute'>\ninterface Entry {\n  canonical: Canonical\n  owner: Context\n  lease(ctx: Context): PublicationLease\n}\nconst roots = new WeakMap<object, Map<object | undefined, Map<string, Entry>>>()\nconst published = new WeakMap<ToolDefinition, { root: object; current(): boolean }>()\n/** Exact live source identity; a matching name or output contract grants nothing. */\nexport function ownsPublication(ctx: Context, tool: ToolDefinition): boolean {\n  const owner = published.get(tool)\n  return owner?.root === (ctx.root ?? ctx) && owner.current()\n}\n\n/**\n * Acquire under a stable plugin-owned scoped context, whose lifetime must cover\n * every consumer. All acquires for a scope/name must share that owner context\n * and canonical object. Only explicit grant membership changes rotate identity.\n *\n * Entitlement and dispatch are snapshotted on grant insertion. There are no live\n * positive predicates: narrowing or transferring authority requires explicit\n * revocation and regrant, rotating the definition outside step preparation.\n * A source discovered in this lifecycle permanently suppresses fallback.\n * Descendant leases share the ancestor source owner and its single definition.\n * Same-layer foreign insertion still fails at the host's duplicate check before\n * tools/change; transparent takeover of that case is deliberately unsupported.\n */\nexport async function acquire(ctx: Context, scope: object | undefined, name: string, canonical: Canonical): Promise<PublicationLease> {\n  const { scopeOf, scopeChainOf } = await loadScopes()\n  ctx.fiber.assertActive()\n  if (scopeOf(ctx) !== scope) throw new Error('Publication scope must match its registration context')\n  const root = ctx.root ?? ctx\n  let scopes = roots.get(root)\n  if (!scopes) { scopes = new Map(); roots.set(root, scopes) }\n  let names = scopes.get(scope)\n  if (!names) { names = new Map(); scopes.set(scope, names) }\n  const existing = names.get(name)\n  if (existing) {\n    if (existing.canonical !== canonical) throw new Error('Conflicting canonical publication definition')\n    return existing.lease(ctx)\n  }\n  // Route before creating a child definition: host inheritance must retain all\n  // restrictions between the source owner and the consuming agent.\n  for (const ancestor of [...scopeChainOf(scope).slice(1), undefined]) {\n    if (ancestor === scope) continue\n    const source = scopes.get(ancestor)?.get(name)\n    if (!source) continue\n    if (source.canonical !== canonical) throw new Error('Conflicting canonical publication definition')\n    const lease = source.lease(source.owner)\n    ctx.effect(() => () => lease.dispose())\n    return lease\n  }\n  const availableTools = ctx.get('tools')\n  if (!availableTools) throw new Error('Publication requires the tools service')\n  const tools = availableTools\n  const grants = new Set<PublicationGrant>()\n  const owned = new Set<ToolDefinition>()\n  // Public toolSet exposes the admitted definition, not which `when` contribution\n  // admitted it. Conservatively bind every eligible same-agent grant as a veto:\n  // losing any captured grant cancels; no hidden or later grant can sustain work.\n  const active = new Map<AbortController, ReadonlySet<PublicationGrant>>()\n  const cancelGrant = (grant: PublicationGrant) => {\n    for (const [controller, captured] of active) if (captured.has(grant)) {\n      controller.abort(new Error('Publication authorization withdrawn'))\n    }\n  }\n  let unregister: (() => void) | undefined\n  let definition: ToolDefinition | undefined\n  let retired = false, busy = false, closed = false, leases = 0\n  const eligible = (agent: Agent) => [...grants].filter(grant => grant.agent === agent && grant.entitled)\n  const attempt = (errors: unknown[], action: () => void) => {\n    try { action() } catch (error) { errors.push(error) }\n  }\n  const finish = (errors: unknown[]) => {\n    if (errors.length) throw new AggregateError(errors, 'Publication lifecycle cleanup failed')\n  }\n  const withdraw = () => {\n    const undo = unregister\n    unregister = undefined\n    definition = undefined\n    undo?.()\n  }\n  const sourceExists = () => {\n    // Scan each ancestor independently: a child restriction cannot hide its source.\n    for (const ancestor of [...scopeChainOf(scope), undefined]) {\n      if (tools.definitions(ancestor).some(candidate => candidate.name === name && !owned.has(candidate))) return true\n    }\n    return false\n  }\n  const refresh = (rotate = false) => {\n    if (busy || closed) return\n    busy = true\n    try {\n      if (sourceExists()) retired = true\n      if (rotate || retired || grants.size === 0) withdraw()\n      if (retired || grants.size === 0 || unregister) return\n      const next: ToolDefinition = { ...canonical, name, execute: async (args, exec) => {\n        if (definition !== next || !exec.agent || !exec.toolSet || tools.executable(name, exec.agent, exec.toolSet) !== next) {\n          return denied()\n        }\n        const matching = eligible(exec.agent)\n        if (!matching.length || matching.some(grant => grant.dispatch !== matching[0].dispatch)) return denied()\n        const controller = new AbortController()\n        const caller = exec.signal\n        const abort = () => controller.abort(caller?.reason)\n        let onCancel: () => void = () => {}\n        const cancellation = new Promise<Outcome<never>>(resolve => {\n          onCancel = () => resolve(cancelled(true))\n          controller.signal.addEventListener('abort', onCancel, { once: true })\n        })\n        active.set(controller, new Set(matching))\n        if (caller?.aborted) abort()\n        else caller?.addEventListener('abort', abort, { once: true })\n        try {\n          if (controller.signal.aborted) return cancelled(false)\n          // Race observes late success/rejection without retaining the active grant or\n          // caller listener. Cancellation cannot prove arbitrary provider effects stopped.\n          // InvocationLifetime.run awaits foreign work, so it cannot bound this handoff.\n          const work = Promise.resolve(matching[0].dispatch(args, { ...exec, signal: controller.signal }))\n          return await Promise.race([work, cancellation])\n        } finally {\n          active.delete(controller)\n          caller?.removeEventListener('abort', abort)\n          controller.signal.removeEventListener('abort', onCancel)\n        }\n      } }\n      owned.add(next)\n      definition = next\n      published.set(next, { root, current: () => definition === next && !closed && !retired })\n      unregister = publicationRegistration(ctx, () => tools.register(next, { when: async activation => {\n        const matching = eligible(activation.agent)\n        if (!matching.length || matching.some(grant => grant.dispatch !== matching[0].dispatch)) return false\n        for (const grant of matching) if (!grant.present || await grant.present(activation)) return true\n        return false\n      } }))\n      // Registration emits synchronously; recheck after its guarded notification.\n      if (sourceExists()) { retired = true; withdraw() }\n    } catch (error) {\n      const errors: unknown[] = [error]\n      attempt(errors, withdraw)\n      finish(errors)\n    } finally { busy = false }\n  }\n  const unwatch = ctx.on('tools/change', () => refresh(), { global: true, prepend: true })\n  const entry: Entry = { canonical, owner: ctx, lease(owner) {\n    if (owner !== ctx) throw new Error('Publication consumers must share a stable owner context')\n    ++leases\n    let disposed = false\n    const local = new Set<() => void>()\n    return {\n      grant(grant) {\n        if (disposed || closed) throw new Error('Publication lease is disposed')\n        if ([...grants].some(candidate => candidate.consumer === grant.consumer && candidate.agent === grant.agent)) {\n          throw new Error('Duplicate publication consumer grant')\n        }\n        // Do not retain the caller's mutable object or callback properties.\n        const captured = Object.freeze({ ...grant })\n        grants.add(captured)\n        try { refresh(true) } catch (error) {\n          grants.delete(captured)\n          const errors: unknown[] = [error]\n          attempt(errors, withdraw)\n          attempt(errors, () => captured.cancel?.())\n          finish(errors)\n        }\n        let active = true\n        const revoke = () => {\n          if (!active) return\n          active = false\n          local.delete(revoke)\n          if (!grants.delete(captured)) return\n          const errors: unknown[] = []\n          attempt(errors, () => cancelGrant(captured))\n          attempt(errors, () => refresh(true))\n          attempt(errors, () => captured.cancel?.())\n          finish(errors)\n        }\n        local.add(revoke)\n        return revoke\n      },\n      async ready() {\n        for (;;) {\n          if (disposed || closed) throw new Error('Publication lease is disposed')\n          const pending = unregister\n          if (!pending) return\n          try { await publicationReady(pending) }\n          catch (error) { if (pending === unregister) throw error }\n          // Another consumer can rotate this shared source while it is queued.\n          // Its replacement, rather than the cancelled generation, owns readiness.\n          if (pending === unregister) return\n        }\n      },\n      dispose() {\n        if (disposed) return\n        disposed = true\n        const errors: unknown[] = []\n        for (const revoke of [...local]) attempt(errors, revoke)\n        if (--leases === 0) attempt(errors, close)\n        finish(errors)\n      },\n    }\n  } }\n  const close = () => {\n    if (closed) return\n    closed = true\n    const remaining = [...grants]\n    grants.clear()\n    for (const grant of remaining) cancelGrant(grant)\n    if (names!.get(name) === entry) names!.delete(name)\n    const errors: unknown[] = []\n    attempt(errors, unwatch)\n    attempt(errors, withdraw)\n    for (const grant of remaining) attempt(errors, () => grant.cancel?.())\n    finish(errors)\n  }\n  names.set(name, entry)\n  ctx.effect(() => close)\n  refresh()\n  return entry.lease(ctx)\n}\n"
