      "path": "src/projections/native/read-dedup.ts",
      "content": "import type { Context } from '../../adapter/dsh/types.js'\nimport type { Agent } from '../../adapter/dsh/types.js'\nimport type { GenerateOptions, StreamChunk } from '../../adapter/dsh/types.js'\nimport type { ToolDefinition, ToolExecution, ToolExecutionResult, ToolExecutionToken } from '../../adapter/dsh/types.js'\nimport { publicToolName } from '../../policy.js'\nimport { CAPABILITIES, OBSERVED_READ_TOOLS } from '../../capabilities/registry.js'\nimport { exactJson, observeRead, unchangedContent } from './read-observation.js'\nimport { generation, readRecord, requestProof } from './read-evidence.js'\nimport type { EvidenceState, ReadRecord } from './read-evidence.js'\n\nconst READS = new Set(OBSERVED_READ_TOOLS.map(publicToolName))\nconst harmless = new Set(CAPABILITIES.filter(entry => !entry.mutates).map(entry => publicToolName(entry.rawName)))\nconst MAX_AGENTS = 16, MAX_RECORDS = 32, MAX_BODY_BYTES = 2 * 1024 * 1024\n\n/** Scope-owned, bounded evidence. This never caches execution values or skips file authority/IO. */\nexport function createNativeReadDedup(ctx: Context): { wrap(tool: ToolDefinition): ToolDefinition; dispose(): void } {\n  if (typeof ctx.on !== 'function') return { wrap: tool => tool, dispose() {} }\n  const states = new Map<Agent, EvidenceState>()\n  const pending = new Map<ToolExecutionToken, { state: EvidenceState; entry: ReadRecord }>()\n  const disposers: (() => void)[] = []\n  let stopped = false\n  const forget = (agent: Agent) => {\n    states.delete(agent)\n    for (const [token, candidate] of pending) if (candidate.state.agent === agent) pending.delete(token)\n  }\n  const current = (agent: Agent): EvidenceState | undefined => {\n    if (stopped) return\n    const value = generation(agent.session)\n    const previous = states.get(agent)\n    if (value === undefined) { forget(agent); return }\n    if (previous?.session === agent.session && previous.generation === value) return previous\n    forget(agent)\n    if (states.size >= MAX_AGENTS) {\n      const oldest = states.keys().next().value\n      if (oldest) forget(oldest)\n    }\n    const state: EvidenceState = { agent, session: agent.session, generation: value, epoch: 0, records: [], proof: new Map() }\n    states.set(agent, state)\n    return state\n  }\n  const finalized = (exec: Readonly<ToolExecution>, result: Readonly<ToolExecutionResult>) => {\n    const candidate = pending.get(exec.token)\n    pending.delete(exec.token)\n    if (!exec.agent || exec.parent) return\n    if (!harmless.has(exec.name)) { forget(exec.agent); return }\n    if (!candidate || result.isError || exactJson(result.content) !== exactJson([{ type: 'text', text: candidate.entry.body }])\n      || current(exec.agent) !== candidate.state) return\n    const state = candidate.state\n    if (state.records.some(entry => entry.callId === exec.callId)) { forget(exec.agent); return }\n    state.records.push(candidate.entry)\n    while (state.records.length > MAX_RECORDS || state.records.reduce((size, entry) => size + Buffer.byteLength(entry.body), 0) > MAX_BODY_BYTES) {\n      const removed = state.records.shift()\n      if (removed) state.proof.delete(removed)\n    }\n  }\n  const stream = async function* (options: GenerateOptions, next: () => AsyncIterable<StreamChunk>): AsyncIterable<StreamChunk> {\n    if (options.purpose || stopped) { yield* next(); return }\n    if (!options.sessionId) {\n      for (const state of states.values()) { state.proof.clear(); state.epoch++ }\n      yield* next()\n      return\n    }\n    const matching = [...states.values()].filter(state => state.session.id === options.sessionId)\n    // A reused session id cannot transfer evidence between owners.\n    if (matching.length !== 1) { for (const state of matching) forget(state.agent); yield* next(); return }\n    const previous = matching[0]!\n    const state = current(previous.agent)\n    if (!state) { yield* next(); return }\n    const epoch = ++state.epoch\n    state.proof.clear()\n    const proof = () => { try { return requestProof(options, state) } catch { return new Map<ReadRecord, string>() } }\n    const before = proof()\n    let finished = false\n    for await (const chunk of next()) {\n      if (chunk.type === 'finish') finished = chunk.reason.kind === 'stop' || chunk.reason.kind === 'tool-calls'\n      yield chunk\n    }\n    if (!finished || options.signal?.aborted || current(state.agent) !== state || state.epoch !== epoch) return\n    const after = proof()\n    state.proof = new Map([...before].filter(([entry, id]) => after.get(entry) === id))\n  }\n  disposers.push(ctx.on('tools/result', (exec, result) => { try { finalized(exec, result) } catch { if (exec.agent) forget(exec.agent) } }))\n  disposers.push(ctx.on('llm/stream', stream))\n  disposers.push(ctx.on('session/event', (session, event) => {\n    try {\n      for (const previous of [...states.values()]) {\n        if (previous.session !== session) continue\n        if (event.type === 'sandbox/mode') { forget(previous.agent); continue }\n        const state = current(previous.agent)\n        if (!state || event.type !== 'tool/result') continue\n        const message = event.data.message\n        for (const entry of state.records) {\n          if (entry.callId !== message.toolCallId) continue\n          if (message.isError || message.source.callId !== entry.callId || !message.id\n            || exactJson(message.content) !== exactJson([{ type: 'text', text: entry.body }])\n            || (entry.messageId && entry.messageId !== message.id)) { forget(state.agent); break }\n          entry.messageId = message.id\n        }\n      }\n    } catch { for (const state of [...states.values()]) if (state.session === session) forget(state.agent) }\n  }))\n  disposers.push(ctx.on('agent/disposed', ({ agent }) => { forget(agent) }))\n  disposers.push(ctx.on('session/disposed', session => { for (const state of [...states.values()]) if (state.session === session) forget(state.agent) }))\n  return {\n    wrap(tool) {\n      if (!READS.has(tool.name) || tool.finalizeContent) return tool\n      return { ...tool, finalizeContent(exec, result) {\n        try {\n          if (!exec.agent || !exec.token || exec.callId.length > 256) return\n          const state = current(exec.agent)\n          const observation = state && observeRead(tool, exec, result)\n          if (!state || !observation) return\n          for (const [entry, messageId] of state.proof) {\n            if (entry.key !== observation.key || entry.body !== observation.body || messageId.length > 256) continue\n            const text = unchangedContent(observation.body, entry.callId, messageId)\n            if (text) return [{ type: 'text', text }]\n          }\n          pending.set(exec.token, { state, entry: readRecord(observation, exec) })\n        } catch { if (exec.agent) forget(exec.agent) }\n        return undefined\n      } }\n    },\n    dispose() {\n      stopped = true\n      states.clear()\n      pending.clear()\n      for (const dispose of disposers.splice(0)) { try { dispose() } catch { /* Scope teardown continues. */ } }\n    },\n  }\n}\n"
    },
    {
      "path": "src/projections/native/result-render.ts",
      "content": "/** Stored rows remain distinct from source-operation completeness and item JSON chunks. */\nconst object = (value: unknown): value is Record<string, unknown> => !!value && typeof value === 'object' && !Array.isArray(value)\nconst text = (value: unknown): string => JSON.stringify(value) ?? 'null'\nconst bytes = (value: string): number => Buffer.byteLength(JSON.stringify([{ type: 'text', text: value }]))\nexport function renderResult(args: Record<string, unknown>, value: Record<string, unknown>): string {\n  const id = value.id ?? (object(value.reference) ? value.reference.refId : undefined) ?? args.id\n  if (value.status === 'released') return 'Released cached reference ' + text(id) + '. No business files were changed.'\n  const reference = object(value.reference) ? value.reference : {}\n  const source = object(value.source) ? value.source : {}\n  const header = ['=== RESULT: ' + text(id) + ' ===',\n    '[Notice: root=' + text(source.root ?? value.root ?? args.root ?? '(current session cwd)') + '; sourceTotal=' + text(value.sourceTotal)\n      + '; filteredTotal=' + text(value.total) + '; contentHash=' + text(value.contentHash) + '.]',\n    '[Notice: producer=' + text(reference.producerTool) + '; createdAt=' + text(reference.createdAt)\n      + '; ttlMs=' + text(reference.ttlMs) + '; totalBytes=' + text(reference.totalBytes) + '.]']\n  if (object(value.source)) header.push('[Source execution: ' + text(value.source) + ']')\n  if (source.itemEncoding === 'tagged-json-v1') header.push('[Notice: Stored rows encode items or item JSON chunks. Join chunks for the same index in byteOffset order before parsing; a final chunk alone is not a complete item.]')\n  const items: unknown[] = Array.isArray(value.items) ? value.items : []\n  let body = header.join('\\n'), displayed = 0\n  for (const item of items) {\n    const next = body + '\\n' + text(item)\n    // Reserve the final paging notice and keep every displayed stored row intact.\n    if (bytes(next) > 60 * 1024) break\n    body = next; displayed++\n  }\n  const displayComplete = displayed === items.length\n  const notice = '[Notice: displayedRows=' + displayed + '; displayComplete=' + displayComplete\n    + '; pageComplete=' + text(value.complete) + '; omitted=' + text(value.omitted)\n    + (displayComplete ? '; nextOffset=' + text(value.nextOffset) : '; repeatOffset=' + text(args.offset ?? 0))\n    + '. Page completeness covers stored rows only; source execution and capture completeness are independent.]'\n  return body + '\\n' + notice + (!displayComplete\n    ? '\\nNext: Repeat the same offset with a smaller limit/maxBytes or fewer fields. Do not advance past undisplayed rows.'\n    : typeof value.nextAction === 'string' ? '\\nNext: ' + value.nextAction : '')\n}\n"
    },
    {
      "path": "src/execution/runtime.ts",
      "content": "/** Runtime discovery is installation-relative; explicit selections never silently fall back. */\nimport { createHash } from 'node:crypto'\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { fileURLToPath } from 'node:url'\nexport interface WorkerSelection { binaryPath?: string }\nexport interface RuntimeOptions { packageRoot?: string; env?: NodeJS.ProcessEnv; platform?: string; arch?: string }\nexport type WorkerResolution = { ok: true; file: string } | { ok: false; reason: string }\nexport const PACKAGE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..')\nexport const PLATFORMS = Object.freeze(['win32-x64', 'linux-x64', 'darwin-arm64', 'darwin-x64'])\nexport function workerName(platform: string = process.platform) { return platform === 'win32' ? 'dsh-ops-worker.exe' : 'dsh-ops-worker' }\n/**\n * Read a JSON file, or name it.\n *\n * A missing receipt used to surface as a raw `ENOENT` out of `readFileSync`: it named\n * a path, but never said that the staged runtime was incomplete, which is the one\n * thing a caller has to know to fix it.\n *\n * Name the artifact **inside the package** (`runtime/<target>/provenance.json`), not the absolute\n * path, and report only the error's code or name: the raw `ENOENT`/`SyntaxError` message embeds the\n * operator's own install path, and an error text that reaches a tool result should not disclose it\n * (#30's point). The package-relative name keeps it actionable — you still know which artifact is\n * wrong.\n */\nfunction readJson(file: string, what: string, shown: string): Record<string, unknown> {\n  let text\n  try { text = fs.readFileSync(file, 'utf8') } catch (error) {\n    throw new Error(`Native worker ${what} at ${shown} could not be read (${(error as NodeJS.ErrnoException)?.code ?? (error as Error)?.name ?? 'unknown'})`)\n  }\n  try { return JSON.parse(text) as Record<string, unknown> } catch (error) {\n    throw new Error(`Native worker ${what} at ${shown} is not valid JSON (${(error as Error)?.name ?? 'unknown'})`)\n  }\n}\n/** Shared receipt check for locally executed and delegated packaged payloads. */\nexport function verifyPackagedWorker(file: string, packageRoot: string, platform: string, arch: string): string {\n  const receipt = readJson(path.join(path.dirname(file), 'provenance.json'), 'provenance receipt',\n    path.posix.join('runtime', `${platform}-${arch}`, 'provenance.json'))\n  const version = readJson(path.join(packageRoot, 'package.json'), 'package manifest', 'package.json').version\n  const digest = createHash('sha256').update(fs.readFileSync(file)).digest('hex')\n  if (!fs.statSync(file).isFile() || receipt.target !== `${platform}-${arch}` || receipt.version !== version\n    || receipt.executable !== workerName(platform) || receipt.sha256 !== digest) throw new Error('Native worker provenance mismatch.')\n  return digest\n}\n/**\n * Resolve the worker without throwing, for a caller that has to *report* an\n * unresolvable host rather than fail on it — a test suite, whose convention for\n * \"this host cannot answer\" is `skipSuite` (exit 77) and never a crash while the\n * module is still loading.\n *\n * The support matrix is checked first, so an unsupported host gets the matrix's\n * own sentence and every other failure keeps the exact reason `resolveWorker`\n * would have thrown. `reason` is a complete clause a caller can put straight into\n * a skip message.\n *\n * @param {object} [config] - same as {@link resolveWorker}.\n * @param {object} [options] - same as {@link resolveWorker}.\n * @returns {{ok: true, file: string}|{ok: false, reason: string}} the attempt.\n */\nexport function tryResolveWorker(config: WorkerSelection = {}, options: RuntimeOptions = {}): WorkerResolution {\n  const platform = options.platform ?? process.platform\n  const arch = options.arch ?? process.arch\n  try {\n    if (!PLATFORMS.includes(`${platform}-${arch}`)) {\n      throw new Error(`this host is ${platform}-${arch}, outside the ${PLATFORMS.join(' / ')} support matrix`)\n    }\n    return { ok: true, file: resolveWorker(config, options) }\n  } catch (error) {\n    return { ok: false, reason: String((error as Error)?.message ?? error) }\n  }\n}\n\nexport function resolveWorker(config: WorkerSelection = {}, { packageRoot = PACKAGE_ROOT, env = process.env, platform = process.platform, arch = process.arch }: RuntimeOptions = {}): string {\n  if (!PLATFORMS.includes(`${platform}-${arch}`)) throw new Error(`dsh-ops supports Windows x64, Linux x64 and macOS (arm64/x64) only; unsupported runtime target ${platform}-${arch}.`)\n  const explicit = config.binaryPath ?? env.DSH_OPS_WORKER_BIN\n  const fromPackage = path.resolve(packageRoot, 'runtime', `${platform}-${arch}`, workerName(platform))\n  const fromSourceTree = path.resolve(packageRoot, 'native', 'target', 'release', workerName(platform))\n  const candidates = explicit !== undefined\n    ? [{ file: explicit, note: 'explicit selection (config.binaryPath / DSH_OPS_WORKER_BIN) — trusting the named path is the whole point of selecting it' }]\n    : [\n      { file: fromPackage, note: 'packaged runtime' },\n      { file: fromSourceTree, note: 'source-tree build (npm run build:ptc) — a dev artifact, with no receipt to verify against' },\n    ]\n  // Compare **resolved, case-folded** paths, never raw strings: Windows is\n  // case-insensitive, so `…\\RUNTIME\\…` names the same file as the candidate we\n  // derived — a substring/spelling test would let it skip verification entirely.\n  const same = (a: string, b: string) => (platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b)\n  const skipped: string[] = []\n  for (const { file, note } of candidates) {\n    if (!path.isAbsolute(file)) throw new Error('Native worker selection must be an absolute path.')\n    let stat\n    try { stat = fs.statSync(file) } catch (error) {\n      // Only \"no such file\" is an ordinary miss for a candidate list. A directory the\n      // process may not traverse, or a symlink that dangles, is a real condition that\n      // an \"unavailable\" message would hide behind the same words.\n      if ((error as NodeJS.ErrnoException).code !== 'ENOENT' && (error as NodeJS.ErrnoException).code !== 'ENOTDIR') throw new Error(`Native worker candidate ${file} could not be inspected: ${(error as Error).message}`)\n      skipped.push(`${file} (absent)`); continue\n    }\n    if (!stat.isFile()) { skipped.push(`${file} (not a regular file)`); continue }\n    // Windows has no execute bit, so this is POSIX-only. Without it, a worker copied\n    // over without its mode was accepted here and failed later as a bare `EACCES`\n    // from `spawn`, which reads as a sandbox problem rather than a missing `chmod`\n    // (report L12).\n    if (platform !== 'win32' && (stat.mode & 0o111) === 0) {\n      throw new Error(`Native worker ${file} is not executable (mode ${(stat.mode & 0o7777).toString(8).padStart(4, '0')}). Run chmod +x on it, or re-stage it with npm run build:ptc; dsh-ops never changes permissions on its own.`)\n    }\n    // Verify the packaged candidate against its receipt. Two limits, stated so nobody\n    // mistakes this for a trust boundary:\n    //   · the receipt sits **beside** the payload, so whoever replaces both passes.\n    //     This catches a build/metadata mismatch (a stale or mistaken runtime), not a\n    //     deliberate substitution — that needs npm's integrity or a signature, which is\n    //     outside this plugin.\n    //   · the selection test is \"is this the candidate we derived\", not a substring of a\n    //     path: `includes('\\runtime\\')` let any absolute path opt itself in (or out).\n    if (same(path.resolve(file), fromPackage)) {\n      verifyPackagedWorker(file, packageRoot, platform, arch)\n    } else {\n      // Not silent: an unverified worker binary is a fact the operator should see.\n      console.warn(`dsh-ops: native worker selected without provenance verification — ${note}: ${file}`)\n    }\n    return file\n  }\n  throw new Error(`Native worker unavailable for ${platform}-${arch}. Tried:\\n${skipped.map(entry => `  ${entry}`).join('\\n')}\\nInstall a runtime-bearing dsh-ops package, or run npm run build:ptc in the source checkout. No ACL repair, shell fallback or automatic download is performed.`)\n}\n"
    },
    {
      "path": "src/kernel/result-lifecycle.ts",
      "content": "import { randomUUID } from 'node:crypto'\nimport { CallBudgetError } from './call-budget.js'\nimport { completeCleanupRoot, recordCleanupFailure, type CleanupReason } from './result-cleanup-registry.js'\nimport { runConfiguredResultCacheGc, scheduleStartupResultCacheGc } from './result-cache-gc.js'\n\nexport interface ResultSession { id: string; header?: { cwd?: string } }\nexport interface LifecycleHost {\n  root?: object\n  on(name: 'session/disposed', callback: (session: ResultSession) => void): unknown\n  on(name: 'session/event', callback: (session: ResultSession, event: { type: string }) => void): unknown\n  effect(callback: () => (() => Promise<void>), label: string): unknown\n  logger?: { warn?: (message: string) => void }\n}\ninterface CleanupEntry {\n  run: () => Promise<void>\n  /** The absolute cache root this cleanup owns, when the caller supplied one. */\n  root?: string\n}\ninterface LiveSession {\n  nonce: string\n  stopped: boolean\n  work: Map<AbortController, Promise<unknown>>\n  cleanup: Map<string, CleanupEntry>\n  closing?: Promise<void>\n}\ninterface Owner { mounts: number; sessions: Map<ResultSession, LiveSession>; expired: WeakSet<ResultSession> }\nconst owners = new WeakMap<object, Owner>()\nfunction owner(ctx: Pick<LifecycleHost, 'root'>): Owner {\n  const key = ctx.root ?? ctx\n  let state = owners.get(key)\n  if (!state) { state = { mounts: 0, sessions: new Map(), expired: new WeakSet() }; owners.set(key, state) }\n  return state\n}\nfunction live(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession): LiveSession {\n  const state = owner(ctx)\n  if (state.expired.has(session)) throw new Error('Result session has expired')\n  // The pinned SessionStore emits its exact stored Session object throughout one lifetime.\n  if ([...state.sessions].some(([other, entry]) => other !== session && other.id === session.id && !entry.stopped)) {\n    throw new Error('Another live session owns this identity')\n  }\n  let entry = state.sessions.get(session)\n  if (!entry) {\n    entry = { nonce: randomUUID(), stopped: false, work: new Map(), cleanup: new Map() }\n    state.sessions.set(session, entry)\n  }\n  if (entry.stopped) throw new Error('Result session is closing')\n  return entry\n}\n/** A reopened persisted session receives a fresh authority binding, even with the same id. */\nexport function resultSessionNonce(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession): string {\n  return live(ctx, session).nonce\n}\n/**\n * Register the physical cleanup of one cache root.\n * @param ctx - the lifecycle owner.\n * @param session - the live session that owns the root.\n * @param key - the in-process cache identity.\n * @param cleanup - the purge; it must throw when physical cleanup did not complete.\n * @param root - the absolute cache root, recorded when cleanup is deferred.\n */\nexport function registerResultCleanup(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession, key: string,\n  cleanup: () => Promise<void>, root?: string): void {\n  live(ctx, session).cleanup.set(key, { run: cleanup, root })\n}\nexport async function withResultSession<T>(ctx: Pick<LifecycleHost, 'root'>, session: ResultSession,\n  signal: AbortSignal | undefined, run: (signal: AbortSignal) => Promise<T>): Promise<T> {\n  const entry = live(ctx, session), controller = new AbortController()\n  const abort = () => controller.abort(signal?.reason)\n  if (signal?.aborted) abort(); else signal?.addEventListener('abort', abort, { once: true })\n  // Defer invocation so teardown always sees the promise before any worker can start.\n  const preceding = [...owner(ctx).sessions].filter(([other]) => other !== session && other.id === session.id)\n    .map(([, entry]) => entry.closing)\n  const work = Promise.resolve().then(async () => {\n    await Promise.allSettled(preceding)\n    if (controller.signal.aborted) throw new CallBudgetError('CANCELLED', 'OPS call cancelled before worker admission; no effects.')\n    return run(controller.signal)\n  })\n  entry.work.set(controller, work)\n  try { return await work }\n  finally { entry.work.delete(controller); signal?.removeEventListener('abort', abort) }\n}\n/** Deferred cleanup attempts kept in memory; the registry keeps the durable record. */\nconst MAX_DEFERRED_CLEANUPS = 256\nconst MAX_DEFERRED_ATTEMPTS = 6\nconst MAX_RETRIES_PER_PASS = 8\nconst RETRY_BASE_MS = 100\nconst RETRY_CAP_MS = 5000\ninterface DeferredCleanup { run: () => Promise<void>; attempts: number; nextAt: number; reason: CleanupReason }\nconst deferred = new Map<string, DeferredCleanup>()\n/** Exposed for diagnostics and the lifecycle tests. */\nexport function deferredCleanupCount(): number {\n  return deferred.size\n}\nfunction backoffMs(attempts: number): number {\n  return Math.min(RETRY_BASE_MS * 2 ** Math.max(0, attempts - 1), RETRY_CAP_MS)\n}\n/** Classify a cleanup failure into the bounded reason vocabulary the registry stores. */\nexport function classifyCleanupFailure(error: unknown): CleanupReason {\n  const message = error instanceof Error ? error.message : String(error)\n  if (/cache grant changed/i.test(message)) return 'cache-grant-changed'\n  if (/authority changed/i.test(message)) return 'authority-changed'\n  if (/read-only|authority unavailable/i.test(message)) return 'read-only'\n  if (/abort|cancel|timeout/i.test(message)) return 'timeout'\n  if (/EPERM|EACCES|EBUSY/.test(message)) return 'eperm'\n  return 'other'\n}\nfunction reportDeferred(ctx: Pick<LifecycleHost, 'logger'>, message: string): void {\n  ctx.logger?.warn?.(message)\n}\n/**\n * Retry deferred cleanups whose backoff has elapsed.\n *\n * A deferred entry keeps the whole closure, so a retry runs the real purge and therefore the real\n * host authority check — read-only still refuses, and that refusal is recorded, not hidden.\n * @param ctx - the lifecycle owner.\n * @param now - current time; tests pass a later value instead of sleeping.\n * @returns how many were attempted, how many completed and how many remain.\n */\nexport async function retryDeferredResultCleanup(ctx: Pick<LifecycleHost, 'root' | 'logger'>,\n  now = Date.now()): Promise<{ attempted: number; completed: number; pending: number }> {\n  let attempted = 0, completed = 0\n  for (const [root, entry] of [...deferred]) {\n    if (entry.nextAt > now || attempted >= MAX_RETRIES_PER_PASS) continue\n    attempted += 1\n    try {\n      await entry.run()\n      deferred.delete(root)\n      completeCleanupRoot(root)\n      completed += 1\n    } catch (error) {\n      const reason = classifyCleanupFailure(error)\n      recordCleanupFailure(root, reason, now)\n      const attempts = entry.attempts + 1\n      if (attempts > MAX_DEFERRED_ATTEMPTS) {\n        deferred.delete(root)\n        reportDeferred(ctx, `dsh-ops: deferred result-cache cleanup for ${root} gave up after ${attempts} attempts (${reason}); the record stays for operator review.`)\n      } else deferred.set(root, { ...entry, attempts, reason, nextAt: now + backoffMs(attempts) })\n    }\n  }\n  return { attempted, completed, pending: deferred.size }\n}\nexport function expireResultSession(ctx: Pick<LifecycleHost, 'root' | 'logger'>, session: ResultSession, disposed = true): Promise<void> {\n  const state = owner(ctx), entry = state.sessions.get(session)\n  if (disposed) state.expired.add(session)\n  if (!entry) return Promise.resolve()\n  if (entry.closing) return entry.closing\n  entry.stopped = true\n  // Publish the barrier before abort listeners can synchronously reopen the same id.\n  entry.closing = Promise.resolve().then(async () => {\n    await Promise.allSettled(entry.work.values())\n    for (const cleanup of entry.cleanup.values()) {\n      try {\n        await cleanup.run()\n        if (cleanup.root !== undefined) completeCleanupRoot(cleanup.root)\n      } catch (error) {\n        const reason = classifyCleanupFailure(error)\n        if (cleanup.root !== undefined) {\n          recordCleanupFailure(cleanup.root, re